{
 "research_concepts": ["offensive lineup personnel effects", "shot mix (shot distance and location categories)", "lineup change via substitution intervals", "shooter and matchup confounding", "lineup coverage and talent control"],
 "methodological_questions": [
  "Does a within-game change of the offensive five, holding shooter and opponent fixed, move shot mix by more than a placebo outcome would?",
  "Can substitution-driven lineup changes be separated from shooter selection, game state and fatigue?",
  "Is the shot-mix outcome measured reliably enough, and is the sample large enough, to detect a personnel effect?",
  "Does the question's premise that the design 'can detect personnel effects' need to be tested rather than assumed?"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-TMP-009",
   "status_as_recorded": "artifact",
   "finding": "PULL_UP exposure-effect diagnostics. Slope holding shot fixed was -0.0255 (0.0061) with lineup FE and -0.0063 (0.0036) without lineup FE; the placebo on other play types was -0.0075 (0.0017). Recorded verdict: artifact_found, attributed to a shooter-level confound. Sample and power not recorded."
  },
  {
   "id": "FAM:SF34",
   "status_as_recorded": "inconclusive",
   "finding": "Opponent lineup adaptation (shot mix when the opposing rim big is off the floor). DRIVE +0.82pp (SE 0.25); 3PA -1.79pp (SE 0.31); rim <=4ft +0.12pp (SE about 0.30, t=+0.4); PPP +0.008 (SE 0.007). Recorded as WEAK/SMALL, with N=1.07M possessions and a small-sample limitation."
  },
  {
   "id": "FAM:SF-PAP-009",
   "status_as_recorded": "supported",
   "finding": "Coverage feasibility gate. 72 team-seasons with at least 200 possessions in both halves passed the gate criteria; |rho(COVERED,TALENT)|=0.042; rho(TALENT,PPP)=+0.027. Sample of 90 team-seasons and 420,993 possessions. Establishes that lineup-level measures can be built and separated from talent; it does not test a personnel effect on shot mix."
  },
  {
   "id": "FAM:SF-PAP-050",
   "status_as_recorded": "inconclusive",
   "finding": "Play-type mix after an absence was described as nearly identical to the pre-absence mix on 148 spells. Recorded verdict null, with no CI and no numeric table. Relevant as a null on a personnel-change outcome, but with no precision reported."
  },
  {
   "id": "FAM:SF-APPS-058",
   "status_as_recorded": "untestable",
   "finding": "On-ball defensive scheme labels. Only 10 of 67 DET possessions (14.9%) and 2 of 60 ORL possessions (3.3%) were labelled; the switches_on field was not populated. Verdict failed_gate."
  },
  {
   "id": "FAM:SF-APPA-005",
   "status_as_recorded": "untestable",
   "finding": "Defensive scheme change with inferred labels: 61.0% within-game and 67.7% cross-game change, with near-uniform transition matrices. The record's own caveat is that the label cannot separate defensive adjustment from offense executing differently."
  },
  {
   "id": "FAM:SF-TMP-016",
   "status_as_recorded": "untestable",
   "finding": "Team heterogeneity in halftime play-type adaptation over 120 team-seasons. Team-season slope SD 0.6733 vs mean sampling SE 0.6508; split-half r -0.026; verdict null."
  },
  {
   "id": "FAM:SF-APPM-021",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Descriptive play-type mix shifts by halftime margin, crunch time and post-run. No inferential tests; the OTHER label is recorded as noisy."
  },
  {
   "id": "FAM:SF-TMP-023",
   "status_as_recorded": "not a hypothesis test",
   "finding": "After-timeout play-type shift on 56,423 possessions, compared with the same game-offense-period-minute. Descriptive; half-court PPP -0.0105 (SE 0.0056)."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-TMP-009",
   "what_failed": "Treating an exposure-slope effect as a personnel/defensive-adaptation effect without holding the shooter fixed and without placebo controls.",
   "why": "Recorded failure mechanism C_artifact: the effect shrinks from -0.0255 to -0.0063 without lineup FE, and the same-shooter placebo on other play types is of similar size, consistent with a shooter-level confound."
  },
  {
   "id": "FAM:SF-APPS-058",
   "what_failed": "Labelling on-ball defensive coverage from matchup/PBP fields at usable rates.",
   "why": "Recorded failure mechanism A_unanswerable: confident label rates of 14.9% and 3.3%, and the switches_on field was not populated; the verdict is failed_gate."
  },
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Measuring within-game and cross-game defensive scheme change from inferred labels.",
   "why": "Recorded failure mechanism A_unanswerable: the inferred label cannot separate real adjustment from offense executing differently; near-uniform transition matrices are consistent with label noise."
  },
  {
   "id": "FAM:SF34",
   "what_failed": "Detecting sub-1pp shot-mix shifts linked to a defensive personnel condition (rim big off floor).",
   "why": "Recorded limitation LIM:small_sample and risk SAMPLE_SIZE_POWER; PPP t=+1.1; the chat verdict was WEAK/SMALL and the record states it will not carry a paper. Failure mechanism is recorded as none."
  }
 ],
 "evidence_establishes": [
  "Lineup-level constructs can be built from these play-by-play data and pass basic feasibility and talent-separation checks (FAM:SF-PAP-009, supported).",
  "Shot-mix shifts of around 1pp are estimable with very large possession counts, and the 3PA and DRIVE shifts in the opponent-big condition are reported with SEs of about 0.25 to 0.31pp (FAM:SF34, inconclusive).",
  "Shooter-level and lineup-level confounding can produce apparent exposure or personnel effects that vanish or change sign under placebo or lineup FE (FAM:SF-TMP-009, artifact).",
  "Inferred defensive or scheme labels are unreliable in this data, so an outcome built on them cannot isolate personnel effects (FAM:SF-APPS-058, FAM:SF-APPA-005)."
 ],
 "evidence_does_not_establish": [
  "No retrieved record tests whether changing the offensive five moves shot mix. The closest records concern opponent-lineup shot mix, play-type mix after absence, and defensive adaptation.",
  "No retrieved record reports a shot-mix effect of an offensive-lineup change with a fixed-shooter design, a placebo outcome, and a power calculation.",
  "The retrieved records do not establish that the design can detect personnel effects; the question's premise is an assumption to be tested, not a result.",
  "FAM:SF-PAP-050's null has no CI and no sample-size power statement, so it does not bound the effect size."
 ],
 "own_inferences": [
  "The question as posed is circular: it presupposes a positive detection in order to validate the design. A test would need a falsifiable criterion, such as a placebo outcome that should not move.",
  "Shot mix is probably less label-sensitive than defensive scheme labels, because shot distance and result are direct fields. Shot-type categories (rim, mid-range, 3PA) derived from distance are likely to be more reliable, but this has not been verified.",
  "Substitution timing is likely endogenous: coaches sub on fatigue, foul trouble and momentum, so lineup changes could be selected on the same game state that drives shot selection (RTM_SELECTION-like confounding).",
  "A mechanical component is plausible: a change of the rim-scoring big changes rim share by construction if the shooter pool changes too (MECHANICAL_FLOOR-like)."
 ],
 "uncertainties": [
  "The data catalog (fields for shot location, shooter ID and the substitution intervals) was not retrieved in this session; field completeness is assumed, not checked.",
  "The exact sample of lineup changes with a stable shooter pool and stable opponent is unknown; the number of qualifying substitution events could be small.",
  "Playoff versus regular-season comparability is unknown; the data span three seasons, and drift in shot mix across seasons is possible (DRIFT_NONSTATIONARITY).",
  "The retrieved records do not state the effect size of an offensive-lineup change on shot mix, so the expected magnitude and the power of the test are unknown."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The records show that label-based outcomes (FAM:SF-APPS-058, FAM:SF-APPA-005) and unadjusted exposure effects (FAM:SF-TMP-009) fail. That shifts the plan away from inferred labels and toward direct shot-distance outcomes, with shooter FE and placebo outcomes. FAM:SF34 shows that around 1pp shifts are detectable only at very large N, which moves the decision from a plain proceed to proceed_with_changes with a power gate. The circular framing of the question is also rewritten as a falsifiable hypothesis."
 },
 "testability": {
  "p_testable": 0.5,
  "blocking_constraints": [
   {
    "code": "RTM_SELECTION",
    "text": "Substitutions are made in response to game state, fatigue and foul trouble, so lineup changes are not randomly assigned. Shot mix can move with these conditions and not with the lineup itself."
   },
   {
    "code": "CONFOUNDING",
    "text": "Shooter identity, opponent defense and score context are correlated with the offensive five. FAM:SF-TMP-009 shows the apparent effect shrinking when lineup and shooter are controlled."
   },
   {
    "code": "SAMPLE_SIZE_POWER",
    "text": "FAM:SF34 reports sub-1pp shot-mix shifts with SEs around 0.25 to 0.31pp, and the record says WEAK/SMALL. A lineup-change test may be underpowered unless the number of qualifying changes is large."
   },
   {
    "code": "PLACEBO_DEPENDENCE",
    "text": "The artifact in FAM:SF-TMP-009 was detected because a same-shooter placebo on other play types was run. Without an equivalent placebo, a shot-mix effect cannot be separated from shooter selection."
   }
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": ["FAM:SF-TMP-009", "FAM:SF34", "FAM:SF-PAP-009", "FAM:SF-PAP-050", "FAM:SF-APPS-058", "FAM:SF-APPA-005"],
  "summary": "No retrieved record tests whether an offensive-lineup change moves shot mix. Related records cover opponent-lineup shot mix (SF34, inconclusive, small sample), play-type mix after absence (SF-PAP-050, null without CI), exposure-effect artifacts from shooter confounding (SF-TMP-009, artifact), and lineup coverage feasibility (SF-PAP-009, supported). The question is therefore not already answered, but the design lessons are reusable."
 },
 "risks": [
  {
   "code": "CONFOUNDING",
   "text": "Shooter, opponent and game-state confounding can produce shot-mix shifts that appear to be personnel effects. FAM:SF-TMP-009 shows the apparent effect shrinking under lineup and shooter control."
  },
  {
   "code": "RTM_SELECTION",
   "text": "Substitutions are triggered by performance, foul trouble and fatigue, so lineup changes are selected on conditions that also move shot mix."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "Shot-mix shifts of about 1pp (FAM:SF34) need large samples; the number of qualifying lineup changes with stable shooters is unknown."
  },
  {
   "code": "MECHANICAL_FLOOR",
   "text": "Replacing a rim-scoring big can change rim share by construction when the shooter pool changes, so a detected shift may be arithmetic rather than behavioural."
  },
  {
   "code": "LABEL_ERROR",
   "text": "Inferred scheme labels are unreliable (FAM:SF-APPS-058, FAM:SF-APPA-005). Shot type derived from shot distance is safer but its classification rules must be fixed and validated."
  },
  {
   "code": "PLACEBO_DEPENDENCE",
   "text": "Any claimed effect must be shown to be specific to shot mix and to the offensive lineup, using placebo outcomes such as the same shooter's non-shot events or other teams' lineup changes."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "Team-level heterogeneity is weakly measured (FAM:SF-TMP-016, split-half r -0.026). Per-lineup shot-mix estimates may be noisy and should be shrunk or pooled."
  },
  {
   "code": "DRIFT_NONSTATIONARITY",
   "text": "Shot-mix and substitution patterns change across 2022-23 to 2024-25 and between regular season and playoffs; season and phase must be controlled or modelled."
  },
  {
   "code": "MULTIPLE_TESTING",
   "text": "Several shot-type outcomes (rim, mid-range, 3PA, DRIVE, POST_UP) and several lineup contrasts create a multiplicity risk; FAM:SF38 relied on Holm correction for this reason."
  }
 ],
 "predicted_outcome": {
  "supported": 0.3,
  "rejected": 0.1,
  "untestable": 0.12,
  "artifact": 0.23,
  "uncertain": 0.25
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "Within-game change in shot mix (rim share, midrange share, 3PA share) when the offensive five changes by substitution, holding the shooter pool and opponent defense fixed, compared with a placebo outcome. The question's premise that the design detects personnel effects is treated as a hypothesis to test, not as an assumption.",
  "unit": "Offensive possession nested in lineup-change event (substitution interval), with shooter and opponent as fixed effects.",
  "sample": "NBA 2022-23, 2023-24 and 2024-25 regular season and playoffs, per-game play-by-play, substitution rotation intervals and starters. Include only changes where a shooter pool can be matched before and after the change. Exclude garbage time and intervals with fewer than a pre-set number of possessions.",
  "power": "Pre-specify a minimum number of qualifying lineup-change events and a minimum effect size of practical interest (for example 1pp rim share). Compute the detectable effect from the realised count before analysis. If the minimum is not met, report the design as underpowered rather than run the test.",
  "controls": "Shooter fixed effects; opponent defense fixed effects; game-state controls (score margin, period, time remaining); season and phase fixed effects; team fixed effects. Placebo lineup changes (same team, same shooter, non-shot outcomes) and an alternative-team placebo. Shot type is derived from shot distance using a fixed rule validated on a held-out sample.",
  "falsification": "The effect must exceed the placebo outcome and must vanish under a permuted-timing placebo that keeps shooter and opponent fixed. A non-zero shift on a placebo outcome (for example shooter non-shot events or other teams' lineup changes) falsifies the design as specified, as in FAM:SF-TMP-009.",
  "multiplicity": "Pre-register one primary outcome (rim share) and one primary contrast; treat the other shot types as secondary with Holm correction, following the approach used in FAM:SF38.",
  "decision_rule": "Claim a personnel effect only if the primary contrast exceeds a pre-set threshold, survives shooter and opponent FE, exceeds the placebo outcomes, and is stable across seasons. Report an artifact if the effect shrinks under shooter FE or appears on placebo outcomes. Report underpowered if the qualifying event count is below the pre-set minimum.",
  "data_version": "Per-game NBA stats API files for 2022-23, 2023-24 and 2024-25 regular season and playoffs, as available on 2026-11-02. Derived play-type possession records from the Neo4j graph are used only for descriptive checks, not as the shot-mix outcome."
 }
}

